// MAL: física en Update (depende del framerate)
void Update()
{
    rb.AddForce(Vector3.forward * 10f); // inconsistente!
}

// BIEN: física en FixedUpdate (intervalo fijo, por defecto 0.02s)
void FixedUpdate()
{
    rb.AddForce(Vector3.forward * 10f); // consistente
}

// BIEN: input en Update, fuerza en FixedUpdate
private Vector3 inputDir;
void Update()
{
    inputDir = new Vector3(Input.GetAxis("Horizontal"), 0, Input.GetAxis("Vertical"));
}
void FixedUpdate()
{
    rb.AddForce(inputDir * speed);
}

// Congelar rotación en todos los ejes (útil para un personaje que no debe volcarse)
rb.constraints = RigidbodyConstraints.FreezeRotation;

// Congelar solo rotación en Y
rb.constraints = RigidbodyConstraints.FreezeRotationY;

// Congelar posición en Y (objeto que solo se mueve en el plano XZ)
rb.constraints = RigidbodyConstraints.FreezePositionY;

// Combinar constraints con el operador |
rb.constraints = RigidbodyConstraints.FreezePositionY | RigidbodyConstraints.FreezeRotation;

